while (my $line = <$fh>) {
  $line_no++;
  chomp $line;
  my @f = split /'"\\t/, "'$line;
  die "expected 7 columns at line $line_no'"\\n\" unless @f == 7;
  my ("'$gene, $lfc, $p) = ($f[0], $f[2], $f[5]);
  die "empty gene at line $line_no'"\\n\" unless length "'$gene;
  die "non-finite lfc at line $line_no: $lfc'"\\n\" unless "'$lfc =~ /''^[-+]?(?:'"\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?"'$/ && $lfc + 0 == $lfc + 0;
  die "bad p at line $line_no: $p'"\\n\" unless "'$p =~ /''^[-+]?(?:'"\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?"'$/ && $p >= 0 && $p <= 1;
  push @rows, { gene => $gene, lfc => $lfc + 0, p => $p + 0, idx => scalar @rows };
}
close $fh;
my $m = @rows;
die "no rows'"\\n\" unless "'$m;
my @ord = sort { $rows[$a]{p} <=> $rows[$b]{p} || $a <=> $b } 0..$#rows;
my @q;
my $min = 1;
for (my $rank = $m; $rank >= 1; $rank--) {
  my $idx = $ord[$rank-1];
  my $val = $rows[$idx]{p} * $m / $rank;
  $val = 1 if $val > 1;
  $min = $val if $val < $min;
  $q[$idx] = $min;
}
open my $oh, ">", $out or die "write $out: $!";
print {$oh} "gene_id'"\\tlog2_fold_change\\tp_value\\tfdr\\n\";
for my "'$r (@rows) {
  my $q = $q[$r->{idx}];
  die "bad q for $r->{gene}'"\\n\" unless defined "'$q && $q >= 0 && $q <= 1;
  printf {$oh} "%s'"\\t%.17g\\t%.17g\\t%.17g\\n\", "'$r->{gene}, $r->{lfc}, $r->{p}, $q;
}
close $oh;
open my $mh, ">", "/workspace/final_answer/method.json" or die $!;
print {$mh} "{'"\\\"method\\\":\\\"DESeq2\\\"}\\n\";
close "'$mh;
open my $lh, ">>", "/workspace/run_trace/execution.log" or die $!;
